import{_ as a,o as s,c as r,ag as t}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"Pressure washers","description":"","frontmatter":{},"headers":[],"relativePath":"car-wash/pressure-washers.md","filePath":"car-wash/pressure-washers.md"}'),o={name:"car-wash/pressure-washers.md"};function n(h,e,l,c,d,i){return s(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="pressure-washers" tabindex="-1">Pressure washers <a class="header-anchor" href="#pressure-washers" aria-label="Permalink to &quot;Pressure washers&quot;">​</a></h1><p>Pressure washers are the self-service option: the player parks, walks up to a washer, and cleans the vehicle level by level. Each dirt level removed is paid.</p><h2 id="where-they-are" tabindex="-1">Where they are <a class="header-anchor" href="#where-they-are" aria-label="Permalink to &quot;Where they are&quot;">​</a></h2><p>Two ways, and you can use both:</p><ul><li><strong>World props</strong>: every prop listed in <code>ManualModels</code> becomes a pressure washer, wherever the map has one. By default it is <code>prop_gas_airunit01</code>, the air unit found at gas stations.</li><li><strong>Stations you place</strong>: add an entry to <code>ManualStations</code> in <code>/nay</code>, stand where you want it and press <strong>Use my position</strong>.</li></ul><p>With <code>ShowBlips</code> on, placed stations show on the map.</p><h2 id="how-players-use-them" tabindex="-1">How players use them <a class="header-anchor" href="#how-players-use-them" aria-label="Permalink to &quot;How players use them&quot;">​</a></h2><ul><li>With <code>InteractionMode</code> set to <code>key</code>, players walk up to the washer and press <strong>E</strong>.</li><li>With <code>target</code>, they use the target eye (ox_target or qb-target).</li></ul><p>The vehicle&#39;s dirt level and the price per level are shown. Cleaning removes one level every <code>ManualSecondsPerLevel</code> seconds, and each level costs <code>ManualPricePerLevel</code>, taken from the account set in <code>Account</code>. Players can stop at any time and only pay for what they cleaned.</p><p>Turn every pressure washer off with <code>ManualEnabled</code>. All settings are on the <a href="/car-wash/settings#pressure-washers">Settings</a> page.</p>',10)])])}const w=a(o,[["render",n]]);export{u as __pageData,w as default};
